class Solution(object):
    def getFolderNames(self, names):
        """
        :type names: List[str]
        :rtype: List[str]
        """
        d = collections.defaultdict(int)
        ans = []
        for name in names:
            if name in d:
                k = d[name]
                while "{}({})".format(name, k) in d:
                    k += 1
                d[name] = k + 1
                ans.append("{}({})".format(name, k))
                d["{}({})".format(name, k)] = 1
            else:
                ans.append(name)
                d[name] = 1
        return ans
